import csv, re, collections
ver={r['peptide'] for r in csv.DictReader(open('/workspace/analysis_work/pq_all_n100_fast/psm_rank.txt'),delimiter='\\t') if r['confident']=='Yes'}
raw=collections.defaultdict(set); canon=collections.defaultdict(set)
def add(seq,p):
 if not p:return
 raw[seq].add(p)
 if p.startswith('tr|') or p.startswith('sp|'):
  x=p.split('|'); canon[seq].add(x[1])
 else: canon[seq].add(p)
for r in csv.DictReader(open('data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular'),delimiter='\\t'):
 if r['Sequence'] in ver:
  for p in r['Proteins'].split(';'):add(r['Sequence'],p)
for r in csv.DictReader(open('data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular'),delimiter='\\t'):
 if r['Sequence'] in ver:
  for p in r['Protein(s)'].split(','):add(r['Sequence'],p)
print('raw pairs',sum(len(raw[p]) for p in ver),'canon pairs',sum(len(canon[p]) for p in ver),'unique proteins canon',len(set().union(*canon.values())))
print('multiple canon')
for p in sorted(ver):
 if len(canon[p])>1: print(p, sorted(canon[p]),'raw',sorted(raw[p]))
print('all output lines canonical sorted-by-input:')
for p in sorted(ver):
 for x in sorted(canon[p]): print(p,x,sep='\\t')
PY"

